86	        ailego::ThreadPool::TaskGroup::Pointer task_group)
87	        : task_group_(std::move(task_group)) {}
88	
89	    //! Submit a task to be executed asynchronous
90	    void submit(ailego::ClosureHandler &&task) override {
91	      while (task_group_->pending_count() >= kMaxQueueSize) {
